<template>
	<view class="container">
		<u-loading-page :loading="true" v-if="load" fontSize="28rpx" />
		<block  v-else>
		<view class="sign-info">
			<view class="sign-info-container">
				<view class="sign-info-container-item" :class="{'selected':item.yet==1}" v-for="(item,index) in result" :key="index">
					<text class="date-text">{{item.day}}</text>
				</view>
			</view>
			<button type="button" class="sign-btn" :disabled="edit==0" @click="sign">{{edit==1?'点击签到':'今日已签到'}}</button>
		</view>
		<scroll-view scroll-y="true" class="scroll" @scrolltolower="loadMore">
			<view class="money-items" v-if="lists.length>0">
				<view class="money-item" v-for="(item,index) in lists" :key="index">
					<image src="/static/my/money-add.png" mode="widthFix" class="left-img" />
					<view class="center">
						<view class="tit">{{item.title}}</view>
						<view class="time">{{item.add_time}}</view>
					</view>
					<view class="right">
						<text>+{{item.money + item.extra_money}}</text>
					</view>
				</view>
				<u-loadmore class="load-more" :status="hasMore?'loading':'nomore'" :nomoreText="noMore" />
			</view>
			<view class="empty-container" v-else>
				<u-empty text="暂无相关数据" :icon="emptyIcon" />
			</view>
		</scroll-view>
		</block>
	</view>
</template>

<script>
	var _this;
	export default {
		data() {
			return {
				edit:0,
				result:[],
				pageIndex: 1,
				pageSize: 20,
			}
		},
		onLoad(e) {
			_this = this;
			_this.get_user_sign()
			_this.get_user_sign_list()
		},
		methods: {
			async get_user_sign(){
				const params = {
					step: 1,
				}
				const data = await _this.$post('port/user_sign', params)
				if(data.code==-50){
					uni.$u.toast(data.msg,()=>{
						_this.finish()
					})
				}else if(data.code==-1){
					_this.edit = data.result.edit
					_this.result = data.result.result
				}else{
					uni.$u.toast(data.msg)
				}
				if (_this.load) {
					_this.load = false
				}
			},
			async sign(){
				const params = {
					step: 2,
				}
				const data = await _this.$post('port/user_sign', params)
				if(data.code==200){
					uni.$u.toast(data.msg)
					_this.get_user_sign()
					_this.pageIndex = 1
					_this.lists = []
					_this.get_user_sign_list()
				}else{
					uni.$u.toast(data.msg)
				}
			},
			loadMore(){
				if(_this.hasMore){
					_this.pageIndex++
					_this.get_user_sign_list()
				}
			},
			async get_user_sign_list(){
				const params = {
					pageIndex: _this.pageIndex,
					pageSize: _this.pageSize,
					step: 3,
				}
				const data = await _this.$post('port/user_sign', params)
				if(data.code==200){
					_this.lists.push(...data.result.list)
					_this.hasMore = data.result.list.length >= _this.pageSize
				}else{
					_this.hasMore = false
				}
			}
		}
	}
</script>

